INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-002-37', 'p0066', 'jinshu', 'a05-002', '《晉書·卷二》', '帝於是使鎮東將軍毌丘儉、揚州刺史文欽等距之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-002-38', 'p0066', 'jinshu', 'a05-002', '《晉書·卷二》', '鎮東大將軍毋丘儉、揚州刺史文欽舉兵作亂，矯太后令移檄郡國，為壇盟於西門之外，各遣子四人質于吳以請救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-002-39', 'p0066', 'jinshu', 'a05-002', '《晉書·卷二》', '毌丘儉、文欽之亂，大軍東征，帝兼中領軍，留鎮洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-002-40', 'p0066', 'jinshu', 'a05-002', '《晉書·卷二》', '吳使文欽、唐咨、全端、全懌等三萬餘人來救誕，諸將逆擊，不能禦。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-013-41', 'p0066', 'jinshu', 'a05-013', '《晉書·卷十三》', '」正元元年正月，鎮東將軍毋丘儉、揚州刺史文欽反，兵俱敗，誅死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-037-42', 'p0066', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '孚次壽春，遣毌丘儉、文欽等進討。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-039-43', 'p0066', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '」毌丘儉、文欽果不服，舉兵反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0066-a05-040-44', 'p0066', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '參大將軍軍事，從景帝討毌丘儉、文欽於樂嘉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-0', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '諸葛誕言於司馬景王曰：「致人而不至於人者，此之謂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-1', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '先時領牙門，給事鎮東諸葛誕，誕不以為能也，欲遣還護軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-2', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '臣松之檢諸書都無此事，至諸葛誕反，司馬文王始挾太后及帝與俱行耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-3', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '以鎮南將軍諸葛誕為鎮東大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-4', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '甲子，吳大將孫峻等衆號十萬至壽春，諸葛誕拒擊破之，斬吳左將軍留贊，獻捷于京都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-5', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '秋七月，以征東大將軍胡遵為衞將軍，鎮東大將軍諸葛誕為征東大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-6', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '甲子，以征東大將軍諸葛誕為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-7', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '乙亥，諸葛誕不就徵，發兵反，殺揚州刺史樂綝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-8', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '丁丑，詔曰：「諸葛誕造為凶亂，盪覆揚州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-9', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」己卯，詔曰：「諸葛誕造構逆亂，迫脅忠義，平寇將軍臨渭亭侯龐會、騎督偏將軍路蕃，各將左右，斬門突出，忠壯勇烈，所宜嘉異。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-10', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '諸葛誕創造凶亂，主簿宣隆、部曲督秦絜秉節守義，臨事固爭，為誕所殺，所謂無比干之親而受其戮者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-004-11', 'p0067', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '三年春二月，大將軍司馬文王陷壽春城，斬諸葛誕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-013-12', 'p0067', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '諸葛誕反，大將軍司馬文王議自詣壽春討誕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-013-13', 'p0067', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '臣松之以為諸葛誕舉淮南以與吳，孫壹率三百人以歸魏，謂吳有釁，本非有理之言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-014-14', 'p0067', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」帝於是發切詔，斥免諸葛誕、鄧颺等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-017-15', 'p0067', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '諸葛誕反，掩襲殺綝，詔悼惜之，追贈衞尉，謚曰愍侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-022-16', 'p0067', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '諸葛誕作亂壽春，司馬文王率六軍軍丘頭，泰總署行臺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-022-17', 'p0067', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '前此諸葛誕、鄧颺等馳名譽，有四䆫八達之誚，帝疾之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-023-18', 'p0067', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '案晉書，諸葛誕反，大將軍東征，峕坐稱疾，為司馬文王所法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-027-19', 'p0067', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '諸葛誕反，昶據夾石以逼江陵，持施績、全熈使不得東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-027-20', 'p0067', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '吳嘗大發衆集建業，揚聲欲入攻揚州，刺史諸葛誕使基策之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-027-21', 'p0067', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '諸葛誕反，基以本官行鎮東將軍，都督揚、豫諸軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-22', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '諸葛誕戰於東關，不利，乃令誕、儉對換。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-23', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '大將軍統中外軍討之，別使諸葛誕督豫州諸軍從安風津擬壽春，征東將軍胡遵督青、徐諸軍出於譙、宋之間，絕其歸路。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-24', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '曹爽誅後，進欽為前將軍以安其心，後代諸葛誕為揚州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-25', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '自曹爽之誅，欽常內懼，與諸葛誕相惡，無所與謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-26', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '諸葛誕字公休，琅邪陽都人，諸葛豐後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-27', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：是時，當世俊士散騎常侍夏侯玄、尚書諸葛誕、鄧颺之徒，共相題表，以玄、疇四人為四聡，誕、備八人為八達，中書監劉放子熈、孫資子密、吏部尚書衞臻子烈三人，咸不及比，以父居勢位，容之為三豫，凡十五人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-28', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '漢晉春秋曰：蔣班、焦彝言於諸葛誕曰：「朱異等以大衆來而不能進，孫綝殺異而歸江東，外以發兵為名，而內實坐須成敗，其歸可見矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-29', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '諸葛誕夫婦聚會神巫，淫祀求福，伏尸淮南，舉族誅夷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-30', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '東安公繇，諸葛誕外孫，欲殺俶，因誅楊駿，誣俶謀逆，遂夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-31', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吳大將軍孫峻等號十萬衆，將渡江，鎮東將軍諸葛誕遣艾據肥陽，艾以與賊勢相遠，非要害之地，輒移屯附亭，遣泰山太守諸葛緒等於黎漿拒戰，遂走之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-32', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '甘露二年，徵諸葛誕為司空，時會喪寧在家，策誕必不從命，馳白文王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-33', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '以討諸葛誕功，進爵陳侯，屢讓不受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-028-34', 'p0067', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '評曰：王淩風節格尚，毌丘儉才識拔幹，諸葛誕嚴毅威重，鍾會精練策數，咸以顯名，致茲榮任，而皆心大志迂，不慮禍難，變如發機，宗族塗地，豈不謬惑邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-033-35', 'p0067', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '二十年，聞魏大將軍諸葛誕據壽春以叛，姜維復率衆出駱谷，至芒水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-044-36', 'p0067', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '二十年，魏征東大將軍諸葛誕反於淮南，分關中兵東下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-047-37', 'p0067', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '江表傳曰：是歲權遣諸葛壹偽叛以誘諸葛誕，誕以步騎二萬迎壹於高山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-048-38', 'p0067', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '十二月朔丙申，大風雷電，魏使將軍諸葛誕、胡遵等步騎七萬圍東興，將軍王昶攻南郡，毌丘儉向武昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-048-39', 'p0067', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '魏諸葛誕入壽春，峻引軍還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-048-40', 'p0067', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '五月，魏征東大將軍諸葛誕以淮南之衆保壽春城，遣將軍朱成稱臣上疏，又遣子靚、長史吳綱諸牙門子弟為質。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-048-41', 'p0067', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '三年春正月，諸葛誕殺文欽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-050-42', 'p0067', 'sanguozhi', 'a04-050', '《三國志·吳書五》', '及魏大將諸葛誕以壽春來附，而全懌、全端、全煒、全儀等並因此際降魏，全熈謀泄見殺，由是諸全衰弱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-055-43', 'p0067', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '魏遣諸葛誕、胡遵等攻東興，諸葛恪率軍拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-055-44', 'p0067', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '太平二年，魏大將軍諸葛誕據壽春來降，魏人圍之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-056-45', 'p0067', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '是歲魏遣胡遵、諸葛誕等出東興，異督水軍攻浮梁，壞之，魏軍大破。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-058-46', 'p0067', 'sanguozhi', 'a04-058', '《三國志·吳書十三》', '太平二年，魏將諸葛誕舉壽春降，拜抗為柴桑督，赴壽春，破魏牙門將偏將軍，遷征北將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-059-47', 'p0067', 'sanguozhi', 'a04-059', '《三國志·吳書十四》', '後諸葛壹偽叛以誘魏將諸葛誕，權潛軍待之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-060-48', 'p0067', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '後襲業領兵，救諸葛誕於壽春，出城先降，魏以為平東將軍，封臨湘侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-064-49', 'p0067', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '魏以吳軍入其疆土，恥於受侮，命大將胡遵、諸葛誕等率衆七萬，欲攻圍兩塢，圖壞隄遏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a04-064-50', 'p0067', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '魏大將軍諸葛誕舉壽春叛，保城請降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-002-51', 'p0067', 'jinshu', 'a05-002', '《晉書·卷二》', '諸葛誕、毌丘儉、王昶、陳泰、胡遵都督四方，王基、州泰、鄧艾、石苞典州郡，盧毓、李豐掌選舉，傅嘏、虞松參計謀，鍾會、夏侯玄、王肅、陳本、孟康、趙酆、張緝預朝議，四海傾注，朝野肅然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-002-52', 'p0067', 'jinshu', 'a05-002', '《晉書·卷二》', '」乃遣諸葛誕督豫州諸軍自安風向壽春，征東將軍胡遵督青、徐諸軍出譙宋之間，絕其歸路。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-002-53', 'p0067', 'jinshu', 'a05-002', '《晉書·卷二》', '尋進號都督，統征東將軍胡遵、鎮東將軍諸葛誕伐吳，戰于東關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-002-54', 'p0067', 'jinshu', 'a05-002', '《晉書·卷二》', '二年夏五月辛未，鎮東大將軍諸葛誕殺揚州刺史樂綝，以淮南作亂，遣子靚為質於吳以請救。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-002-55', 'p0067', 'jinshu', 'a05-002', '《晉書·卷二》', '暨諸葛誕滔天作逆，稱兵揚楚，欽、咨逋罪，同惡相濟，帥其蝥賊，以入壽春，憑阻淮山，敢距王命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-013-56', 'p0067', 'jinshu', 'a05-013', '《晉書·卷十三》', '四年三月，吳將為寇，鎮東將軍諸葛誕破走之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-013-57', 'p0067', 'jinshu', 'a05-013', '《晉書·卷十三》', '」景元元年五月，有成濟之變及諸葛誕誅，皆其應也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-013-58', 'p0067', 'jinshu', 'a05-013', '《晉書·卷十三》', '後三年，即魏甘露二年，諸葛誕又反淮南，吳遣將救之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-039-59', 'p0067', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '帝征諸葛誕，留顗鎮守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0067-a05-040-60', 'p0067', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '帝新執朝權，恐方鎮有異議，使充詣諸葛誕，圖欲伐吳，陰察其變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-0', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '辛未，以長水校尉鄧艾行安西將軍，與征西將軍陳泰并力拒維。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-1', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸未，安西將軍鄧艾大破蜀大將姜維於上邽，詔曰：「兵未極武，醜虜摧破，斬首獲生，動以萬計，自頃戰克，無如此者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-2', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '冬十月，蜀大將姜維寇洮陽，鎮西將軍鄧艾拒之，破維於侯和，維遁走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-3', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '今使征西將軍鄧艾督帥諸軍，趣甘松、沓中以羅取維，雍州刺史諸葛緒督諸軍趣武都、高樓，首尾踧討。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-4', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '自鄧艾、鍾會率衆伐蜀，所至輙克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-5', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '五年乙卯，以征西將軍鄧艾為太尉，鎮西將軍鍾會為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-6', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '咸熈元年春正月壬戌，檻車徵鄧艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-004-7', 'p0068', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '是月，鍾會反於蜀，為衆所討；鄧艾亦見殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-022-8', 'p0068', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '」淮從泰計，使泰率討蜀護軍徐質、南安太守鄧艾等進兵圍之，斷其運道及城外流水。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-022-9', 'p0068', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '鄧艾、胡奮、王秘亦到，即與艾、祕等分為三軍，進到隴西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-026-10', 'p0068', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '次子弘，亦猛毅有招風，以隴西太守隨鄧艾伐蜀有功，咸熈中為振威護軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-027-11', 'p0068', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '時兖州刺史鄧艾屯樂嘉，儉使文欽將兵襲艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-12', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '大將軍遣兖州刺史鄧艾督泰山諸軍萬餘人至樂嘉，示弱以誘之，大將軍尋自洙至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-13', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '鄧艾字士載，義陽棘陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-14', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '宣王奇之，辟之為掾，世語曰：鄧艾少為襄城典農部民，與石苞皆年十二三。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-15', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '方鄧艾以萬人入江由之危險，鍾會以二十萬衆留劒閣而不得進，三軍之士已飢，艾雖戰勝克將，使劉禪數日不降，則二將之軍難以反矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-16', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '征西將軍鄧艾，矜功失節，實應大辟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-17', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '世語曰：咸寧中，積射將軍樊震為西戎牙門，得見辭，武帝問震所由進，震自陳曾為鄧艾伐蜀時帳下將，帝遂尋問艾，震具申艾之忠，言之流涕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-18', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '四年秋，乃下詔使鄧艾、諸葛緒各統諸軍三萬餘人，艾趣甘松、沓中連綴維，緒趣武街、橋頭絕維歸路。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-19', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '鄧艾追姜維到陰平，簡選精銳，欲從漢德陽入江由、左儋道詣緜竹，趣成都，與諸葛緒共行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-20', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會內有異志，因鄧艾承制專事，密白艾有反狀，世語曰：會善效人書，於劒閣要艾章表白事，皆易其言，令辭指悖傲，多自矜伐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-21', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '會得文王書云：「恐鄧艾或不就徵，今遣中護軍賈充將步騎萬人徑入斜谷，屯樂城，吾自將十萬屯長安，相見在近。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-22', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」會得書，驚呼所親語之曰：「但取鄧艾，相國知我能獨辦之；今來大重，必覺我異矣，便當速發。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-23', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」及會白鄧艾不軌，文王將西，悌復曰：「鍾會所統，五六倍於鄧艾，但可勑會取艾，不足自行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-028-24', 'p0068', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '鄧艾矯然彊壯，立功立事，然闇於防患，咎敗旋至，豈遠知乎諸葛恪而不能近自見，此蓋古人所謂目論者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-033-25', 'p0068', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '秋八月，維為魏大將軍鄧艾所破于上邽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-033-26', 'p0068', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '是歲，姜維復率衆出侯和，為鄧艾所破，還住沓中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-033-27', 'p0068', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '六年夏，魏大興徒衆，命征西將軍鄧艾、鎮西將軍鍾會、雍州刺史諸葛緒數道並攻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-033-28', 'p0068', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '冬，鄧艾破衞將軍諸葛瞻於緜竹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-035-29', 'p0068', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '六年冬，魏征西將軍鄧艾伐蜀，自陰平由景谷道旁入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-035-30', 'p0068', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」建稽首曰：「臣竊聞天下之論，皆謂鄧艾見枉，陛下知而不理，此豈馮唐之所謂『雖得頗、牧而不能用』者乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-036-31', 'p0068', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '苞子遵為尚書，隨諸葛瞻於緜竹，與鄧艾戰，死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-039-32', 'p0068', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '及鄧艾至蜀，聞皓姦險，收閉，將殺之，而皓厚賂艾左右，得免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-042-33', 'p0068', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '景耀六年冬，魏大將軍鄧艾克江由，長驅而前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-042-34', 'p0068', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '景耀六年，後主從譙周之計，遣使請降於鄧艾，其書，正所造也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-043-35', 'p0068', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '權留蜀子崇，為尚書郎，隨衞將軍諸葛瞻拒鄧艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-043-36', 'p0068', 'sanguozhi', 'a04-043', '《三國志·蜀書十三》', '恢弟子球，羽林右部督，隨諸葛瞻拒鄧艾，臨陣授命，死于緜竹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-37', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '後主旣降鄧艾，斌詣會於涪，待以交友之禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-38', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '更整勒戎馬，與鎮西大將軍胡濟期會上邽，濟失誓不至，故維為魏大將鄧艾所破於段谷，星散流離，死者甚衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-39', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '魏大將軍司馬望拒之，鄧艾亦自隴右，皆軍于長城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-40', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '五年，維率衆出漢、侯和，為鄧艾所破，還住沓中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-41', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '及鍾會將向駱谷，鄧艾將入沓中，然後乃遣右車騎廖化詣沓中為維援，左車騎張翼、輔國大將軍董厥等詣陽安關口以為諸圍外助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-42', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '月餘，維為鄧艾所摧，還住陰平。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-43', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '而鄧艾自陰平由景谷道傍入，遂破諸葛瞻於緜竹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-44', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '會旣構鄧艾，艾檻車徵，因將維等詣成都，自稱益州牧以叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-45', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '鄧艾之入江由，士衆鮮少，維進不能奮節緜竹之下，退不能總帥五將，擁衞蜀主，思後圖之計，而乃反覆於逆順之間，希違情於難兾之會，以衰弱之國，而屢觀兵於三秦，已滅之邦，兾理外之奇舉，不亦闇哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-044-46', 'p0068', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '但鄧艾詭道傍入，出於其後，諸葛瞻旣敗，成都自潰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a04-045-47', 'p0068', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '蜀平後，征西將軍鄧艾聞其名，請為主簿，及書招，欲與相見，皆不往。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-002-48', 'p0068', 'jinshu', 'a05-002', '《晉書·卷二》', '諸葛誕、毌丘儉、王昶、陳泰、胡遵都督四方，王基、州泰、鄧艾、石苞典州郡，盧毓、李豐掌選舉，傅嘏、虞松參計謀，鍾會、夏侯玄、王肅、陳本、孟康、趙酆、張緝預朝議，四海傾注，朝野肅然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-002-49', 'p0068', 'jinshu', 'a05-002', '《晉書·卷二》', '帝屯汝陽，遣兗州刺史鄧艾督太山諸軍進屯樂嘉，示弱以誘之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-002-50', 'p0068', 'jinshu', 'a05-002', '《晉書·卷二》', '」征西將軍鄧艾以為未有釁，屢陳異議。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-002-51', 'p0068', 'jinshu', 'a05-002', '《晉書·卷二》', '於是徵四方之兵十八萬，使鄧艾自狄道攻姜維於沓中，雍州刺史諸葛緒自祁山軍于武街，絕維歸路，鎮西將軍鍾會帥前將軍李輔、征蜀護軍胡烈等自駱谷襲漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-002-52', 'p0068', 'jinshu', 'a05-002', '《晉書·卷二》', '十一月，鄧艾帥萬餘人自陰平踰絕險至江由，破蜀將諸葛瞻於緜竹，斬瞻，傳首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-002-53', 'p0068', 'jinshu', 'a05-002', '《晉書·卷二》', '表鄧艾為太尉，鍾會為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-003-54', 'p0068', 'jinshu', 'a05-003', '《晉書·卷三》', '鄧艾雖矜功失節，然束手受罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-005-55', 'p0068', 'jinshu', 'a05-005', '《晉書·卷五》', '爾乃取鄧艾於農瑣，引州泰於行役，委以文武，各善其事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-013-56', 'p0068', 'jinshu', 'a05-013', '《晉書·卷十三》', '」是後鍾會、鄧艾破蜀，會譖艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-013-57', 'p0068', 'jinshu', 'a05-013', '《晉書·卷十三》', '」明年，鄧艾、鍾會皆夷滅，赦蜀土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-013-58', 'p0068', 'jinshu', 'a05-013', '《晉書·卷十三》', '」四年，鍾會、鄧艾伐蜀，剋之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-036-full-59', 'p0068', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '鄧艾、鍾會之伐蜀也，瓘以本官持節監艾、會軍事，行鎮西軍司，給兵千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-036-full-60', 'p0068', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '鄧艾本營將士復追破檻車出艾，還向成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-036-full-61', 'p0068', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '初，杜預聞瓘殺鄧艾，言於眾曰：「伯玉其不免乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-036-62', 'p0068', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '鄧艾、鍾會之伐蜀也，瓘以本官持節監艾、會軍事，行鎮西軍司，給兵千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-036-63', 'p0068', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '鄧艾本營將士復追破檻車出艾，還向成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-036-64', 'p0068', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '初，杜預聞瓘殺鄧艾，言於眾曰：「伯玉其不免乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-037-65', 'p0068', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '征西將軍陳泰與安西將軍鄧艾進擊維，維退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-042-66', 'p0068', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '」濬曰：「吾始懼鄧艾之事，畏禍及，不得無言，亦不能遣諸胸中，是吾褊也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-042-67', 'p0068', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '初，鄧艾之誅也，文帝以艾久在隴右，素得士心，一旦夷滅，恐邊情搔動，使彬密察之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0068-a05-042-68', 'p0068', 'jinshu', 'a05-042', '《晉書-卷四十二・列傳第十二》', '彬還，白帝曰：「鄧艾忌克詭狹，矜能負才，順從者謂爲見事，直言者謂之觸迕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-0', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」鍾會對曰：「才同陳思，武類太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-1', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」於是侍郎鍾會退論次焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-2', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」　傅暢晉諸公贊曰：帝常與中護軍司馬望、侍中王沈、散騎常侍裴秀、黃門侍郎鍾會等講宴於東堂，并屬文論。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-3', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」乃令散騎常侍裴秀、給事黃門侍郎鍾會咸與大將軍俱行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-4', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」又命鎮西將軍鍾會由駱谷伐蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-5', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '自鄧艾、鍾會率衆伐蜀，所至輙克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-6', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '五年乙卯，以征西將軍鄧艾為太尉，鎮西將軍鍾會為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-7', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '是月，鍾會反於蜀，為衆所討；鄧艾亦見殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-8', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸巳，詔曰：「前逆臣鍾會構造反亂，聚集征行將士，劫以兵威，始吐姦謀，發言桀逆，逼脅衆人，皆使下議，倉卒之際，莫不驚懾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-004-9', 'p0069', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '庚戌，以虎賁張脩昔於成都馳馬至諸營言鍾會反逆，以至沒身，賜脩弟倚爵關內侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-005-10', 'p0069', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '毌丘儉、鍾會等作亂，咸假其命而以為辭焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-009-11', 'p0069', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '」後移居墓所，景王遣鍾會看之，若才藝德能及父，當收。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-010-12', 'p0069', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '紹子融，字伯雅，與王弼、鍾會俱知名，為洛陽令，參大將軍軍事，與弼、會論易、老義，傳於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-010-13', 'p0069', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '嘗難鍾會「易無互體」，見稱於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-018-14', 'p0069', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '王隱蜀記曰：鍾會平蜀，前後鼓吹，迎悳屍喪還葬鄴，冢中身首如生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-15', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '鍾會為大將軍所昵，聞康名而造之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-16', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '鍾會勸大將軍因此除之，遂殺安及康。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-17', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '又鍾會傳亦云會作司隷校尉時誅康；會作司隷，景元中也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-18', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '干寶云呂安兄巽善於鍾會，巽為相國掾，俱有寵於司馬文王，故遂抵安罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-19', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '嘏常論才性同異，鍾會集而論之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-20', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '司隷校尉鍾會年甚少，嘏以明智交會。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-21', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '臣松之案：傅子前云嘏了夏侯之必敗，不與之交，而此云與鍾會善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-22', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '愚以為夏侯玄以名重致患，釁由外至；鍾會以利動取敗，禍自己出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-021-23', 'p0069', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '嘏若了夏侯之必危，而不見鍾會之將敗，則為識有所蔽，難以言通；若皆知其不終，而情有彼此，是為厚薄由于愛憎，奚豫於成敗哉？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-023-24', 'p0069', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '晉諸公贊曰：康有弘量，綽以明達為稱，楷少與琅邪王戎俱為掾發名，鍾會致之大將軍司馬文王曰：「裴楷清通，王戎簡要。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-024-25', 'p0069', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '若趙括之母，以先請獲免，鍾會之兄，以密言全子，古今此比，蓋為不少。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-025-26', 'p0069', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '』逮鍾會為鎮西將軍，憲英謂從子羊祜曰：『鍾士季何故西出？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-025-27', 'p0069', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '』其後會請子琇為參軍，憲英憂曰：『他日見鍾會之出，吾為國憂之矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-28', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '維聞鍾會諸軍已入漢中，引退還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-29', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '方鄧艾以萬人入江由之危險，鍾會以二十萬衆留劒閣而不得進，三軍之士已飢，艾雖戰勝克將，使劉禪數日不降，則二將之軍難以反矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-30', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」鍾會、胡烈、師纂等皆白艾所作悖逆，變釁以結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-31', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '艾父子旣囚，鍾會至成都，先送艾，然後作亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-32', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '鍾會忌艾威名，搆成其事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-33', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '鍾會字士季，潁川長社人，太傅繇小子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-34', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '臣松之以為鍾會名公之子，聲譽夙著，弱冠登朝，已歷顯仕，景王為相，何容不悉，而方於定虞松表然後乃蒙接引乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-35', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初，文王欲遣會伐蜀，西曹屬邵悌求見曰：「今遣鍾會率十餘萬衆伐蜀，愚謂會單身無重任，不若使餘人行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-36', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '惟鍾會與人意同，今遣會伐蜀，必可滅蜀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-37', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」及會白鄧艾不軌，文王將西，悌復曰：「鍾會所統，五六倍於鄧艾，但可勑會取艾，不足自行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-38', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '近日賈護軍問我，言：『頗疑鍾會不？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-39', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '漢晉春秋曰：文王聞鍾會功曹向雄之收葬會也，召而責之曰：「往者王經之死，卿哭於東市而我不問，今鍾會躬為叛逆而又輒收葬，若復相容，其如王法何！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-40', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '習鑿齒曰：向伯茂可謂勇於蹈義也，哭王經而哀感市人，葬鍾會而義動明主，彼皆忠烈奮勁，知死而往，非存生也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-41', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '弼與鍾會善，會論議以校練為家，然每服弼之高致。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-42', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '何晏以為聖人無喜怒哀樂，其論甚精，鍾會等述之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-028-43', 'p0069', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '評曰：王淩風節格尚，毌丘儉才識拔幹，諸葛誕嚴毅威重，鍾會精練策數，咸以顯名，致茲榮任，而皆心大志迂，不慮禍難，變如發機，宗族塗地，豈不謬惑邪！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-033-44', 'p0069', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '六年夏，魏大興徒衆，命征西將軍鄧艾、鎮西將軍鍾會、雍州刺史諸葛緒數道並攻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-034-45', 'p0069', 'sanguozhi', 'a04-034', '《三國志·蜀書四》', '咸熈元年正月，鍾會作亂於成都，璿為亂兵所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-035-46', 'p0069', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '秋，魏鎮西將軍鍾會征蜀，至漢川，祭亮之廟，令軍士不得於亮墓所左右芻牧樵採。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-042-47', 'p0069', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '明年正月，鍾會作亂成都，後主東遷洛陽，時擾攘倉卒，蜀之大臣無翼從者，惟正及殿中督汝南張通，捨妻子單身隨侍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-044-48', 'p0069', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '魏大將軍鍾會至漢城，與斌書曰：「巴蜀賢智文武之士多矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-044-49', 'p0069', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '六年，維表後主：「聞鍾會治兵關中，欲規進取，宜並遣張翼、廖化督諸軍分護陽安關口、陰平橋頭以防未然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-044-50', 'p0069', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '及鍾會將向駱谷，鄧艾將入沓中，然後乃遣右車騎廖化詣沓中為維援，左車騎張翼、輔國大將軍董厥等詣陽安關口以為諸圍外助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-044-51', 'p0069', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '鍾會攻圍漢、樂二城，遣別將進攻關口，蔣舒開城出降，傅僉格鬬而死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-044-52', 'p0069', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '」　孫盛晉陽秋曰：盛以永和初從安西將軍平蜀，見諸故老，及姜維旣降之後密與劉禪表疏，說欲偽服事鍾會，因殺之以復蜀土，會事不捷，遂至泯滅，蜀人于今傷之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-044-53', 'p0069', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '于時鍾會大衆旣造劒閣，維與諸將列營守險，會不得進，已議還計，全蜀之功，幾乎立矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-044-54', 'p0069', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '干寶曰：姜維為蜀相，國亡主辱弗之死，而死於鍾會之亂，惜哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a04-045-55', 'p0069', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '六年，與維咸在劒閣，共詣降鍾會于涪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-56', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '諸葛誕、毌丘儉、王昶、陳泰、胡遵都督四方，王基、州泰、鄧艾、石苞典州郡，盧毓、李豐掌選舉，傅嘏、虞松參計謀，鍾會、夏侯玄、王肅、陳本、孟康、趙酆、張緝預朝議，四海傾注，朝野肅然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-57', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '帝會公卿謀征討計，朝議多謂可遣諸將擊之，王肅及尚書傅嘏、中書侍郎鍾會勸帝自行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-58', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '帝用嘏及鍾會策，自帥軍而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-59', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '儀兄靜時在壽春，用鍾會計，作禕、儀書以譎靜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-60', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '於是徵四方之兵十八萬，使鄧艾自狄道攻姜維於沓中，雍州刺史諸葛緒自祁山軍于武街，絕維歸路，鎮西將軍鍾會帥前將軍李輔、征蜀護軍胡烈等自駱谷襲漢中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-61', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '鍾會分為二隊，入自斜谷，使李輔圍王含於樂城，又使部將易愷攻蔣斌於漢城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-62', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '維與張翼、廖化合軍守劔閣，鍾會攻之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-63', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '表鄧艾為太尉，鍾會為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-64', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '鍾會遂反於蜀，監軍衞瓘、右將軍胡烈攻會，斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-002-65', 'p0069', 'jinshu', 'a05-002', '《晉書·卷二》', '初，會之伐蜀也，西曹屬邵悌言於帝曰：「鍾會難信，不可令行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-013-66', 'p0069', 'jinshu', 'a05-013', '《晉書·卷十三》', '」是後鍾會、鄧艾破蜀，會譖艾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-013-67', 'p0069', 'jinshu', 'a05-013', '《晉書·卷十三》', '」明年，鄧艾、鍾會皆夷滅，赦蜀土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-013-68', 'p0069', 'jinshu', 'a05-013', '《晉書·卷十三》', '」四年，鍾會、鄧艾伐蜀，剋之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-013-69', 'p0069', 'jinshu', 'a05-013', '《晉書·卷十三》', '鍾會既叛，三軍憤怒，隆隆有聲，兵將怒之徵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-034-70', 'p0069', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '鍾會有寵而忌，祜亦憚之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-034-71', 'p0069', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '鍾會伐蜀，以預爲鎮西長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-036-full-72', 'p0069', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '鄧艾、鍾會之伐蜀也，瓘以本官持節監艾、會軍事，行鎮西軍司，給兵千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-036-full-73', 'p0069', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '紞嘗侍帝，從容論魏晉事，因曰：「臣竊謂鍾會之釁，頗由太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-036-full-74', 'p0069', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '鍾會才見有限，而太祖誇奬太過，嘉其謀猷，盛其名器，居以重勢，委以大兵，故使會自謂算無遺策，功在不賞，輈張跋扈，遂搆凶逆耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-036-75', 'p0069', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '鄧艾、鍾會之伐蜀也，瓘以本官持節監艾、會軍事，行鎮西軍司，給兵千人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-036-76', 'p0069', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '紞嘗侍帝，從容論魏晉事，因曰：「臣竊謂鍾會之釁，頗由太祖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-036-77', 'p0069', 'jinshu', 'a05-036', '《晉書-卷三十六・列傳第六》', '鍾會才見有限，而太祖誇奬太過，嘉其謀猷，盛其名器，居以重勢，委以大兵，故使會自謂算無遺策，功在不賞，輈張跋扈，遂搆凶逆耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-037-78', 'p0069', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '時魏高貴鄉公好才愛士，望與裴秀、王沈、鍾會並見親待，數侍宴筵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-039-79', 'p0069', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '難鍾會易無互體，又與扶風王駿論仁孝孰先，見稱於世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-039-80', 'p0069', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '及鍾會謀反，審問未至，而外人先告之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0069-a05-040-81', 'p0069', 'jinshu', 'a05-040', '《晉書-卷四十・列傳第十》', '鍾會謀反於蜀，帝假充節，以本官都督關中、隴右諸軍事，西據漢中，未至而會死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a03-070-0', 'p0070', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '司馬懿、懿字仲達，即晉宣帝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-002-1', 'p0070', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '督軍御史中丞司馬懿、侍御史鄭渾、羊祕、鮑勛、武周等言：「令如左。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-002-2', 'p0070', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '其以尚書令潁鄉侯陳羣為鎮軍大將軍，尚書僕射西鄉侯司馬懿為撫軍大將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-003-3', 'p0070', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '帝曰：「司馬懿臨危制變，擒淵可計日待也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-008-4', 'p0070', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '」又曰：「司馬懿所向無前，深為弟憂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-021-5', 'p0070', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '時司空陳羣錄尚書事，帝初親萬機，質以輔弼大臣，安危之本，對帝盛稱「驃騎將軍司馬懿，忠智至公，社稷之臣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-028-6', 'p0070', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」　漢晉春秋曰：初，夏侯霸降蜀，姜維問之曰：「司馬懿旣得彼政，當復有征伐之志不？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-033-7', 'p0070', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '八年秋，魏使司馬懿由西城，張郃由子午，曹真由斜谷，斜，余奢反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-033-8', 'p0070', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '魏司馬懿、張郃救祁山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-035-9', 'p0070', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '明日食時，亮謂參佐拊手大笑曰：「司馬懿必謂吾怯，將有彊伏，循山走矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-035-10', 'p0070', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '魏司馬懿才用兵衆，未易可輕，量敵而進，兵家所慎；若丞相必有以筭之，則未見坦然之勳，若無筭以裁之，則非明哲之謂，海內歸向之意也，余竊疑焉，請聞其說。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-040-11', 'p0070', 'sanguozhi', 'a04-040', '《三國志·蜀書十》', '去年臣欲西征，欲令平主督漢中，平說司馬懿等開府辟召。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-044-12', 'p0070', 'sanguozhi', 'a04-044', '《三國志·蜀書十四》', '殷基通語曰：司馬懿誅曹爽，禕設甲乙論平其是非。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-047-13', 'p0070', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '又蔣琬守漢中，聞司馬懿南向，不出兵乘虛以掎角之，反委漢中，還近成都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-047-14', 'p0070', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '又司馬懿前來入舒，旬日便退，蜀在萬里，何知緩急而便出兵乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-048-15', 'p0070', 'sanguozhi', 'a04-048', '《三國志·吳書三》', '司馬懿父子，自握其柄，累有大功，除其煩苛而布其平惠，為之謀主而救其疾，民心歸之，亦已乆矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a04-064-16', 'p0070', 'sanguozhi', 'a04-064', '《三國志·吳書十九》', '加司馬懿先誅王淩，續自隕斃，其子幼弱，而專彼大任，雖有智計之士，未得施用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a05-001-17', 'p0070', 'jinshu', 'a05-001', '《晉書·卷一》', '因謂太子丕曰：「司馬懿非人臣也，必預汝家事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0070-a05-037-18', 'p0070', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '」天子曰：「吾得司馬懿二人，復何憂哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0071-a04-028-0', 'p0071', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '欽殊不悟，乃更厲聲罵大目：「汝先帝家人，不念報恩，而反與司馬師作逆；不顧上天，天不祐汝！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0071-a04-028-1', 'p0071', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '司馬師滔天作逆，廢害二主，辛、癸、高、莽，惡不足喻。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0071-a04-028-2', 'p0071', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '艾遣子惠唐亭侯忠等出其右，司馬師纂等出其左。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0072-a04-004-0', 'p0072', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '乃召侍中王沈、尚書王經、散騎常侍王業，謂曰：「司馬昭之心，路人所知也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-004-0', 'p0073', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '三月，以尚書令司馬孚為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-004-1', 'p0073', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '辛未，以司空司馬孚為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-004-2', 'p0073', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '五月，吳太傅諸葛恪圍合肥新城，詔太尉司馬孚拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-004-3', 'p0073', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '帝受命，遂載王車，與太后別，垂涕，始從太極殿南出，羣臣送者數十人，太尉司馬孚悲不自勝，餘多流涕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-004-4', 'p0073', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '戊辰，復遣太尉司馬孚為後繼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-004-5', 'p0073', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '癸酉，以太尉司馬孚為太傅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-022-6', 'p0073', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '魏氏春秋曰：帝之崩也，太傅司馬孚、尚書右僕射陳泰枕帝尸於股，號哭盡哀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a04-028-7', 'p0073', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '吳太傅諸葛恪圍合肥新城，儉與文欽禦之，太尉司馬孚督中軍東解圍，恪退還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0073-a05-037-8', 'p0073', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '臨終，遺令曰：「有魏貞士河內溫縣司馬孚，字叔達，不伊不周，不夷不惠，立身行道，終始若一。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0074-a03-080b-0', 'p0074', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '司馬朗字伯達，河內溫人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0074-a04-012-1', 'p0074', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '始琰與司馬朗善，晉宣王方壯，琰謂朗曰：「子之弟，聦哲明允，剛斷英跱，殆非子之所及也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0074-a04-015-2', 'p0074', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '司馬朗字伯達，河內溫人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0074-a04-023-3', 'p0074', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '」又司馬朗早有聲名，其族兄芝，衆未之知，惟俊言曰：「芝雖風望不及朗，實理但有優耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0074-a04-028-4', 'p0074', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初，淩與司馬朗、賈逵友善，及臨兖、豫，繼其名跡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-002-0', 'p0075', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '秋七月，兾州大蝗，民饑，使尚書杜畿持節開倉廩以振之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-010-1', 'p0075', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '取士不以一揆，戲志才、郭嘉等有負俗之譏，杜畿簡傲少文，皆以智策舉之，終各顯名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-013-2', 'p0075', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '而詔已拜杜畿為太守，畿已入界。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-013-3', 'p0075', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '又臣上言吏民大小，各懷顧望，謂邑當還，拒太守杜畿，今皆反悔，共迎畿之官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-013-4', 'p0075', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '其邯鄲淳事在王粲傳，蘇林事在劉邵、高堂隆傳，樂詳事在杜畿傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-016-5', 'p0075', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '杜畿字伯侯，京兆杜陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-016-6', 'p0075', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '」彧曰：「杜畿其人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-016-7', 'p0075', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '太祖下令曰：「河東太守杜畿，孔子所謂『禹，吾無閒然矣』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-016-8', 'p0075', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '後勳伏法，太祖得其書，歎曰：「杜畿可謂『不媚於竈』者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-016-9', 'p0075', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '」故尚書僕射杜畿於孟津試船，遂至覆沒，忠之至也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-016-10', 'p0075', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '所問旣了而歸鄉里，時杜畿為太守，亦甚好學，署詳文學祭酒，使教後進，於是河東學業大興。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-016-11', 'p0075', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '杜畿寬猛克濟，惠以康民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0075-a04-028-12', 'p0075', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初以尚書郎為滎陽令，魏氏春秋曰：誕為郎，與僕射杜畿試船陶河，遭風覆沒，誕亦俱溺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-014-0', 'p0076', 'houhanshu', 'a03-014', '《後漢書·卷十四》', '與班固、賈逵共述漢史，傅毅等皆宗事之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-017-1', 'p0076', 'houhanshu', 'a03-017', '《後漢書·卷十七》', '賈逵注國語曰：「折其鋒曰挫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-025-2', 'p0076', 'houhanshu', 'a03-025', '《後漢書·卷二十五》', '」時侍中賈逵薦丕道蓺深明，宜見任用。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-025-3', 'p0076', 'houhanshu', 'a03-025', '《後漢書·卷二十五》', '和帝因朝會召見諸儒，丕與侍中賈逵、尚書令黃香等相難數事，帝善丕說，罷朝，特賜冠幘履韤衣一襲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-035-4', 'p0076', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '」初，中興之後，范升、陳元、李育、賈逵之徒爭論古今學，後馬融荅北地太守劉瓌及玄荅何休，義據通深，由是古學遂明。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-036-5', 'p0076', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '鄭興子衆　范升　陳元　賈逵　張霸子揩　揩子陵　陵弟玄');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-036-6', 'p0076', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '世言左氏者多祖於興，而賈逵自傳其父業，故有鄭、賈之學。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-036-7', 'p0076', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '賈逵字景伯，扶風平陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-036-8', 'p0076', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '賈逵以為紀季不能兄弟同心以存國，乃背兄歸讎，書以譏之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-036-9', 'p0076', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '謂防曰：「賈逵母病，此子無人事於外，無人事謂不廣交通也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-036-10', 'p0076', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '桓譚以不善讖流亡，鄭興以遜辭僅免，賈逵能附會文致，最差貴顯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-036-11', 'p0076', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '賈逵附會文致，謂引左氏明漢為堯後也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-037-12', 'p0076', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '肅宗詔鴻與廣平王羨及諸儒樓望、成封、桓郁、賈逵等，論定五經同異於北宮白虎觀，廣平王羨，明帝子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-037-13', 'p0076', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '東觀記曰「與太常樓望、少府成封、屯騎校尉桓郁、衞士令賈逵等集議」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-039-14', 'p0076', 'houhanshu', 'a03-039', '《後漢書·卷三十九》', '積十餘歲，至永元十年，有司復奏之，侍中賈逵因上書曰：「孔子稱『能以禮讓為國，於從政乎何有』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-042-15', 'p0076', 'houhanshu', 'a03-042', '《後漢書·卷四十二》', '帝甚善之，以其文典雅，特令校書郎賈逵為之訓詁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-048-16', 'p0076', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '會終坐事繫獄，愽士趙愽、校書郎班固、賈逵等，以終深曉春秋，學多異聞，表請之，終又上書自訟，即日貰出，乃得與於白虎觀焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-048-17', 'p0076', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '袁山松書曰「侍中賈逵薦終博達忠直，徵拜郎中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-052-18', 'p0076', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '年十八，至京師，從侍中賈逵質正大義，逵善待之，瑗因留游學，遂明天官、歷數、京房易傳、六日七分。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-052-19', 'p0076', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '賈逵注國語曰：「從後牽曰掎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-059-20', 'p0076', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '賈逵注國語曰：「淈，亂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-059-21', 'p0076', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '往者侍中賈逵摘讖互異三十餘事，諸言讖者皆不能說。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-060a-22', 'p0076', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '」賈逵注云：「繯，還也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-060a-23', 'p0076', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '甞欲訓左氏春秋，及見賈逵、鄭衆注，乃曰：「賈君精而不博，鄭君博而不精。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-064-24', 'p0076', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '中興以來，通儒達士班固、賈逵、鄭興父子，並敦恱之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-074-25', 'p0076', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '賈逵注國語曰：「從後牽曰掎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-079-26', 'p0076', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '扶風杜林傳古文尚書，林同郡賈逵為之作訓，馬融作傳，鄭玄注解，由是古文尚書遂顯于世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-080-27', 'p0076', 'houhanshu', 'a03-080', '《後漢書·卷八十上》', '建初中，肅宗博召文學之士，以毅為蘭臺令史，拜郎中，與班固、賈逵共典校書。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-080-28', 'p0076', 'houhanshu', 'a03-080', '《後漢書·卷八十上》', '和帝時，侍中賈逵薦尤有相如、楊雄之風，召詣東觀，受詔作賦，拜蘭臺令史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-082-29', 'p0076', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '鄭興、賈逵以附同稱顯，桓譚、尹敏以乖忤淪敗，各見本傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-082-30', 'p0076', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '謂桓譚、賈逵、張衡之流也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-092-31', 'p0076', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '賈逵論曆　永元論曆　延光論曆　漢安論曆　熹平論曆　論月食');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-092-32', 'p0076', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '行之未期，章帝復發聖思，考之經讖，使左中郎將賈逵問治曆者衞承、李崇、太尉屬梁鮪、司徒掾嚴勗、太子舍人徐震、鉅鹿公乘蘇統及訢、梵等十人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-098-33', 'p0076', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '」賈逵曰：「六宗謂日宗、月宗、星宗、岱宗、海宗、河宗也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-104-34', 'p0076', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '案宣帝、明帝時，五色鳥羣翔殿屋，賈逵以為胡降徵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a03-113-35', 'p0076', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '」賈逵曰：「陶唐之胤劉累也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-014-36', 'p0076', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '友人河東賈逵謂資曰：「足下抱逸群之才，值舊邦傾覆，主將殷勤，千里延頸，宜崇古賢桑梓之義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-015-37', 'p0076', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '賈逵字梁道，河東襄陵人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-015-38', 'p0076', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '召見計事，大恱之，謂左右曰：「使天下二千石悉如賈逵，吾何憂？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-015-39', 'p0076', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '青龍中，帝東征，乘輦入逵祠，詔曰：「昨過項，見賈逵碑像，念之愴然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-018-40', 'p0076', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '其祝公道一人，已見賈逵傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-019-41', 'p0076', 'sanguozhi', 'a04-019', '《三國志·魏書十九》', '脩與賈逵、王淩並為主簿，而為植所友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-028-42', 'p0076', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '初，淩與司馬朗、賈逵友善，及臨兖、豫，繼其名跡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-028-43', 'p0076', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '干寶晉紀曰：淩到項，見賈逵祠在水側，淩呼曰：「賈梁道，王淩固忠於魏之社稷者，唯尔有神，知之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a04-042-44', 'p0076', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '皆通諸經史，又專精於左氏春秋，自劉歆條例，鄭衆、賈逵父子、陳元方、服虔注說，咸略誦述，不復桉本。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a05-001-45', 'p0076', 'jinshu', 'a05-001', '《晉書·卷一》', '道經賈逵廟，淩呼曰：「賈梁道！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a05-001-46', 'p0076', 'jinshu', 'a05-001', '《晉書·卷一》', '六月，帝寢疾，夢賈逵、王淩為祟，甚惡之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a05-011-47', 'p0076', 'jinshu', 'a05-011', '《晉書·卷十一》', '後至和帝時，賈逵繫作，又加黃道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0076-a05-039-48', 'p0076', 'jinshu', 'a05-039', '《晉書-卷三十九・列傳第九》', '沈探尋善政，案賈逵以來法制禁令，諸所施行，擇善者而從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0077-a04-015-0', 'p0077', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '劉馥字元穎，沛國相人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0077-a04-051-1', 'p0077', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '」遂殺河，使人北迎揚州刺史劉馥，令住歷陽，以丹楊應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-009-0', 'p0079', 'houhanshu', 'a03-009', '《後漢書·卷九》', '丙戌，太中大夫楊彪為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-009-1', 'p0079', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十二月戊戌，司徒黃琬為太尉，司空楊彪為司徒，光祿勳荀爽為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-009-2', 'p0079', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月乙亥，太尉黃琬、司徒楊彪免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-009-3', 'p0079', 'houhanshu', 'a03-009', '《後漢書·卷九》', '甲申，司空淳于嘉為司徒，光祿大夫楊彪為司空，並錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-009-4', 'p0079', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」司空楊彪免，太常趙溫為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-009-5', 'p0079', 'houhanshu', 'a03-009', '《後漢書·卷九》', '戊午，太常楊彪為太尉，錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-009-6', 'p0079', 'houhanshu', 'a03-009', '《後漢書·卷九》', '九月，太尉楊彪、司空張喜罷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-027-7', 'p0079', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '獻帝西遷都，為侍中，同輿輦至長安，封江南亭侯，代楊彪為司空，免，頃之，復為司徒，錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-054-8', 'p0079', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '太尉楊彪，乃祖以來世著名績，其賜公延年杖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-061-9', 'p0079', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '卓議遷都長安，琬與司徒楊彪同諫不從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-061-10', 'p0079', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '後與楊彪同拜光祿大夫，及徙西都，轉司隷校尉，與司徒王允同謀誅卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-064-11', 'p0079', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '歲餘，復徵拜議郎，與諫議大夫馬日磾、議郎蔡邕、楊彪、韓說等並在東觀，校中書五經記傳，補續漢記。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-066-12', 'p0079', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '初平元年，代楊彪為司徒，守尚書令如故。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-066-13', 'p0079', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '每三公缺，楊彪、皇甫嵩皆讓位於瑞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-068-14', 'p0079', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '司空楊彪辟，舉方正、敦樸，徵，皆不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-070-15', 'p0079', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '與楊彪、盧植、蔡邕等典校中書，歷位九卿，遂登台輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-071-16', 'p0079', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '獻帝詔儁與太尉楊彪等十餘人譬郭汜，令與李傕和。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-072-17', 'p0079', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓乃與司徒黃琬、司空楊彪，俱帶鈇鑕詣闕上書，追理陳蕃、竇武及諸黨人，以從人望。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-072-18', 'p0079', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '會公卿議，太尉黃琬、司徒楊彪廷爭不能得，而伍瓊、周珌又固諫之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-072-19', 'p0079', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '太尉楊彪謂暹曰：「古今帝王，無在人臣家者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-072-20', 'p0079', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '帝使楊彪與司空張喜等十餘人和傕、汜，汜不從，遂質留公卿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-072-21', 'p0079', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '』太尉楊彪等曰：『煨不反，臣等敢以死保，車駕可幸其營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-072-22', 'p0079', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '楊彪曰：『臣弘農人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-072-23', 'p0079', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '楊彪、董承及后父執金吾伏完等數十人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a03-074-24', 'p0079', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '故太尉楊彪，歷典二司，元綱極位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-001-25', 'p0079', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏書曰：袁紹宿與故太尉楊彪、大長秋梁紹、少府孔融有隙，欲使公以他過誅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-001-26', 'p0079', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '臣松之以為楊彪亦曾為魏武所困，幾至於死，孔融竟不免於誅滅，豈所謂先行其言而後從之哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-002-27', 'p0079', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '冬十月，授楊彪光祿大夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-002-28', 'p0079', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '魏書曰：己亥，公卿朝朔旦，并引故漢太尉楊彪，待以客禮，詔曰：「夫先王制几杖之賜，所以賔禮黃耇襃崇元老也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-29', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '司徒楊彪曰：「昔盤庚五遷，殷民胥怨，故作三篇以曉天下之民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-30', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '續漢書曰：太尉黃琬、司徒楊彪、司空荀爽俱詣卓，卓言：「昔高祖都關中，十一世後中興，更都洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-31', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '楊彪曰：「自古帝王無在人臣家者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-32', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '楊彪曰：「羣臣共鬬，一人劫天子，一人質公卿，此可行乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-33', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '太尉周忠、皇甫嵩，司徒淳于嘉、趙溫，司空楊彪、張喜等為公，皆辭拜讓瑞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-34', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝紀曰：初，議者欲令天子浮河東下，太尉楊彪曰：「臣弘農人，從此已東有三十六灘，非萬乘所當從也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-35', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '太尉楊彪、太僕韓融近臣從者十餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-36', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '故太尉楊彪，歷典三司，享國極位，操因睚眥，被以非罪，榜楚并兼，五毒俱至，觸情放慝，不顧憲章。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-006-37', 'p0079', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '與楊彪、盧植、蔡邕等典校中書，歷位九卿，遂登台輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-012-38', 'p0079', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '續漢書曰：太尉楊彪與袁術婚姻，術僭號，太祖與彪有隙，因是執彪，將殺焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-013-39', 'p0079', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '朗薦光祿大夫楊彪，且稱疾，讓位於彪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-022-40', 'p0079', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '為車騎將軍何苗所辟，司徒楊彪再加旌命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-026-41', 'p0079', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '」故太尉楊彪收付縣獄，尚書令荀彧、少府孔融等並屬寵：「但當受辭，勿加考掠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0079-a04-026-42', 'p0079', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '數日，求見太祖，言之曰：「楊彪考訊無他辭語。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-001-0', 'p0080', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '蔡邕獨斷曰：「天子以四海為家，故謂所居為行在所。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-001-1', 'p0080', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '奉高皇帝璽綬，蔡邕獨斷曰：「皇帝六璽，皆玉螭虎紐，文曰『皇帝行璽』、『皇帝之璽』、『皇帝信璽』、『天子行璽』、『天子之璽』、『天子信璽』，皆以武都紫泥封之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-008-full-2', 'p0080', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '蔡邕曰：「平城門，正陽之門，與宮連，郊祀法駕所從出，門之最尊者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-008-3', 'p0080', 'houhanshu', 'a03-008', '《後漢書·卷八》', '蔡邕曰：「平城門，正陽之門，與宮連，郊祀法駕所從出，門之最尊者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-010b-full-4', 'p0080', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '皇太后臨朝，蔡邕獨斷曰：「少帝即位，太后即代攝政，臨前殿，朝羣臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-010b-full-5', 'p0080', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '今使御史大夫郗慮持節策詔，其上皇后璽綬，蔡邕獨斷曰：「皇后赤綬玉璽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-010b-full-6', 'p0080', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '初平中，蔡邕始追正和熹之謚，蔡邕集謚議曰：「漢世母氏無謚，至于明帝始建光烈之稱，是後轉因帝號加之以德，上下優劣，混而為一，違禮『大行受大名，小行受小名』之制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-010b-full-7', 'p0080', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '蔡邕曰：「帝女曰公主，姊妹曰長公主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-010b-8', 'p0080', 'houhanshu', 'a03-010b', '《《後漢書》卷十下·皇后紀第十下（獻帝伏皇后節錄）》', '今使御史大夫郗慮持節策詔，其上皇后璽綬，〈蔡邕《獨斷》曰：「皇后赤綬玉璽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-037-9', 'p0080', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '所著七說及書凡三篇，蔡邕等共論序其志，僉以為彬有過人者四：夙智早成，岐嶷也；夙，早也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-040-10', 'p0080', 'houhanshu', 'a03-040', '《後漢書·卷四十上》', '蔡邕獨斷曰：「天子至尊，不敢渫瀆言之，故託於乘輿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-043-11', 'p0080', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '袁山松書曰：「穆著論甚美，蔡邕甞至其家自寫之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-043-12', 'p0080', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '」及穆卒，蔡邕復與門人共述其體行，謚為文忠先生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-043-13', 'p0080', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '袁山松書曰：「蔡邕議曰：『魯季文子，君子以為忠，而謚曰文子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-043-14', 'p0080', 'houhanshu', 'a03-043', '《後漢書·卷四十三》', '蔡邕以為穆貞而孤，又作正交而廣其致焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-044-15', 'p0080', 'houhanshu', 'a03-044', '《後漢書·卷四十四》', '熹平六年，靈帝思感舊德，乃圖畫廣及太尉黃瓊於省內，詔議郎蔡邕為其頌云。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-047-16', 'p0080', 'houhanshu', 'a03-047', '《後漢書·卷四十七》', '」蔡邕月令章句曰：「羽，鳥翼也，以為旌幢麾也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-049-17', 'p0080', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '箸論衡八十五篇，二十餘萬言，袁山松書曰：「充所作論衡，中土未有傳者，蔡邕入吳始得之，恒秘玩以為談助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-049-18', 'p0080', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '」抱朴子曰：「時人嫌蔡邕得異書，或搜求其帳中隱處，果得論衡，抱數卷持去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-052-19', 'p0080', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '」蔡邕銘論曰「呂尚作周太師，其功銘於昆吾之鼎」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-053-20', 'p0080', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '同郡蔡邕深重蟠，及被州辟，乃辭讓之曰：「申屠蟠稟氣玄妙，性敏心通，喪親盡禮，幾於毀滅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-054-21', 'p0080', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '」帝惡之，引賜及議郎蔡邕等入金商門崇德署，戴延之西征記曰：「太極殿西有金商門。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-054-22', 'p0080', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '蔡邕坐直對抵罪，徙朔方。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-054-23', 'p0080', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '熹平中，以博習舊聞，公車徵拜議郎，華嶠書曰：「與馬日磾、盧植、蔡邕等著作東觀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-059-24', 'p0080', 'houhanshu', 'a03-059', '《後漢書·卷五十九》', '漢名臣奏曰，蔡邕曰：「言天體者有三家：一曰周髀，二曰宣夜，三曰渾天。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-060a-25', 'p0080', 'houhanshu', 'a03-060a', '《後漢書·卷六十上》', '蔡邕獨斷曰：「金𡕰者，馬冠也，高廣各四寸，在馬鬉前。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-064-26', 'p0080', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '歲餘，復徵拜議郎，與諫議大夫馬日磾、議郎蔡邕、楊彪、韓說等並在東觀，校中書五經記傳，補續漢記。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-064-27', 'p0080', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '植素善蔡邕，邕前徙朔方，植獨上書請之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-068-28', 'p0080', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '」同志者乃共刻石立碑，蔡邕為其文，旣而謂涿郡盧植曰：「吾為碑銘多矣，皆有慙德，唯郭有道無愧色耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-070-29', 'p0080', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '與楊彪、盧植、蔡邕等典校中書，歷位九卿，遂登台輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-070-30', 'p0080', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」與蔡邕素善，邕卒後，有虎賁士貌類於邕，漢官典職儀曰：「虎賁中郎將，主武賁千五百人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-070-31', 'p0080', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '曹操旣積嫌忌，而郗慮復搆成其罪，遂令丞相軍謀祭酒路粹典略曰：「粹字文蔚，陳留人，少學於蔡邕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-072-32', 'p0080', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '謂忍性屈情，擢用鄭泰、蔡邕、何顒、荀爽等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-078-33', 'p0080', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '又聞前召議郎蔡邕對問於金商門，而令中常侍曹節、王甫等以詔書喻旨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-078-34', 'p0080', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '今羣臣皆以邕為戒，上畏不測之難，下懼劔客之害，謂蔡邕徙朔方時，陽球使刺客追刺邕也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-078-35', 'p0080', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '巡以為諸博士試甲乙科，爭弟高下，更相告言，至有行賂定蘭臺漆書經字，以合其私文者，乃白帝，與諸儒共刻五經文於石，於是詔蔡邕等正其文字。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-078-36', 'p0080', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '詐利旣滋，朋徒日廣，直臣抗議，必漏先言之閒，謂蔡邕對詔，王甫、曹節竊觀之，乃宣布於外，而邕下獄也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-079-37', 'p0080', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '與蔡邕共奏定六經文字。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-080-38', 'p0080', 'houhanshu', 'a03-080', '《後漢書·卷八十上》', '後蔡邕亦造此賦，未成，及見延壽所為，甚竒之，遂輟翰而已。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-080b-39', 'p0080', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '議郎蔡邕深敬之，以為讓宜處高任，乃薦於何進曰：「伏惟幕府初開，博選清英，華髮舊德，並為元龜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-080b-40', 'p0080', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '議郎蔡邕等皆賦詩，彪乃獨作箴曰：「文武將墜，乃俾俊臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-080b-41', 'p0080', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '甞與衡俱遊，共讀蔡邕所作碑文，射愛其辭，還恨不繕寫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-082-42', 'p0080', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '謂襄楷、蔡邕、楊厚等也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-084-43', 'p0080', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '其後蔡邕又題八字曰：『黃絹幼婦，外孫虀臼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-084-44', 'p0080', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '陳留董祀妻者，同郡蔡邕之女也，名琰，字文姬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-092-45', 'p0080', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '蔡邕議云：「梵，清河人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-092-46', 'p0080', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '蔡邕集載：「三月九日，百官會府公殿下，東面，校尉南面，侍中、郎將、大夫、千石、六百石重行北面，議郎、博士西面。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-092-47', 'p0080', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '蔡邕前坐侍中西北，近公卿，與光、晃相難問是非焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-092-48', 'p0080', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '蔡邕月令論曰：「顓頊曆術曰：『天元正月己巳朔旦立春，俱以日月起於天廟營室五度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-092-49', 'p0080', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '觀蔡邕之議，可以言天機矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-092-50', 'p0080', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '勑曰：「前郎中馮光、司徒掾陳晃各訟曆，故議郎蔡邕共補續其志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-092-51', 'p0080', 'houhanshu', 'a03-092', '《二十四史-後漢書-志第二‧律曆中》', '及在東觀，與蔡邕共述律曆記，考驗天官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-093-52', 'p0080', 'houhanshu', 'a03-093', '《二十四史-後漢書-志第三‧律曆下》', '」　蔡邕分星次度數與皇甫謐不同，兼明氣節所在，故載焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-093-53', 'p0080', 'houhanshu', 'a03-093', '《二十四史-後漢書-志第三‧律曆下》', '光和元年中，議郎蔡邕、郎中劉洪補續律曆志，邕能著文，清濁鍾律，洪能為筭，述敘三光。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-093-54', 'p0080', 'houhanshu', 'a03-093', '《二十四史-後漢書-志第三‧律曆下》', '蔡邕戍邊上章曰：「朔方髡鉗徒臣邕稽首再拜上書皇帝陛下：臣邕被受陛下尤異大恩，初由宰府備數典城，以叔父故衞尉質時為尚書，召拜郎中，受詔詣東觀著作，遂與羣儒並拜議郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-094-55', 'p0080', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '謝沈書曰：「太傅胡廣博綜舊儀，立漢制度，蔡邕依以為志，譙周後改定以為禮儀志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-094-56', 'p0080', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」蔡邕曰：「即此詔之謂也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-094-57', 'p0080', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '東都之儀，百官、四姓親家婦女、公主、諸王大夫、蔡邕獨斷曰：「凡與先后有瓜葛者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-094-58', 'p0080', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '謝承書曰：「建寧五年正月，車駕上原陵，蔡邕為司徒掾，從公行，到陵，見其儀，愾然謂同坐者曰：『聞古不墓祭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-094-59', 'p0080', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '蔡邕曰：「五更，長老之稱也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-094-60', 'p0080', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」蔡邕曰：「論語『暮春者，春服旣成，冠者五六人，童子六七人，浴乎沂，風乎舞雩，詠而歸』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-095-61', 'p0080', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '蔡邕獨斷曰：「冬至陽氣始動，夏至陰氣始起，麋鹿角解，故寢兵鼓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-095-62', 'p0080', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '」蔡邕曰：「見客平樂、饗衞士，瓌偉壯觀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-095-63', 'p0080', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '蔡邕獨斷曰：「三公奉璧上殿，向御坐，北面，太常贊曰：『皇帝為君興。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-095-64', 'p0080', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '蔡邕曰：「羣臣朝見之儀，視不晚朝十月朔之故，以問胡廣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-095-65', 'p0080', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '』」蔡邕禮樂志曰：「漢樂四品：一曰大予樂，典郊廟、上陵、殿諸食舉之樂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-097-66', 'p0080', 'houhanshu', 'a03-097', '《二十四史-後漢書-志第七‧祭祀上》', '謝沈書曰蔡邕引中興以來所修者為祭祀志，即邕之意也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-098-67', 'p0080', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '」蔡邕明堂論曰：「明堂者，天子太廟，所以崇禮其祖，以配上帝者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-099-68', 'p0080', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '蔡邕表志曰：「孝明立世祖廟，以明再受命祖有功之義，後嗣遵儉，不復改立，皆藏主其中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-099-69', 'p0080', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '初平中，相國董卓、左中郎將蔡邕等以和帝以下，功德無殊，而有過差，不應為宗，及餘非宗者追尊三后，皆奏毀之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-099-70', 'p0080', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '蔡邕表志曰：「宗廟迭毀議奏，國家大體，班固錄漢書，乃置韋賢傳末。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-100-71', 'p0080', 'houhanshu', 'a03-100', '《二十四史-後漢書-志第十‧天文上》', '謝沈書曰：「蔡邕撰建武已後，星驗著明，以續前志，譙周接繼其下者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-100-72', 'p0080', 'houhanshu', 'a03-100', '《二十四史-後漢書-志第十‧天文上》', '」蔡邕表志曰：「言天體者有三家：一曰周髀，二曰宣夜，三曰渾天。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-103-73', 'p0080', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '蔡邕對曰：「平城門，正陽之門，與宮連，郊祀法駕所由從出，門之最尊者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-103-74', 'p0080', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '蔡邕作伯夷叔齊碑曰「熹平五年，天下大旱，禱請名山，求獲荅應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-103-75', 'p0080', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '蔡邕封事曰：『政有苛暴，則虎狼食人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-105-76', 'p0080', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」蔡邕對曰：「臣聞易傳曰：『大作不時，天降災，厥咎蝗蟲來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-105-77', 'p0080', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '蔡邕對曰：「蝗蟲出，息不急之作，省賦斂之費，進清仁，黜貪虐，分損承安，屈省別藏，以贍國用，則其救也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-107-78', 'p0080', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '時蔡邕以成帝時男子王襃絳衣入宮，上前殿非常室，曰「天帝令我居此」，後王莽篡位。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-107-79', 'p0080', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '上問蔡邕，對曰：「所謂天投蜺者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-108-80', 'p0080', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '蔡邕上書曰：「四年正月朔，日體微傷，羣臣服赤幘，赴宮門之中，無救，乃各罷歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-108-81', 'p0080', 'houhanshu', 'a03-108', '《二十四史-後漢書-志第十八‧五行六》', '蔡邕對問曰：「詔問踐阼以來，災眚屢見，頻歲日蝕、地動，風雨不時，疫癘流行，勁風折樹，河、雒盛溢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-109-82', 'p0080', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '蔡邕作樊陵頌云：「前漢戶五萬，口有十七萬，王莽後十不存一。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-119-83', 'p0080', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '乘輿、金根、安車、立車，蔡邕曰：「五安五立。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-119-84', 'p0080', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」貳轂兩轄，蔡邕曰：「轂外復有一轂抱轄，其外乃復設轄，抱銅置其中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-119-85', 'p0080', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '蔡邕曰：「在最後左騑馬頭上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-119-86', 'p0080', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '蔡邕表志曰：「以文義不著之故，俗人多失其名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-119-87', 'p0080', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '蔡邕表志曰：「國家舊章，而幽僻藏蔽，莫之得見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-120-88', 'p0080', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '蔡邕曰：「鄙人不識，謂之平天冠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a03-120-89', 'p0080', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '蔡邕表志曰：「永平初，詔書下車服制度，中宮皇太子親服重繒厚練，浣已復御，率下以儉化起機。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-001-90', 'p0080', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '謝承後漢書曰：匡少與蔡邕善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-001-91', 'p0080', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '桓譚、蔡邕善音樂，馮翊山子道、王九真、郭凱等善圍棊，太祖皆與埒能。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-004-92', 'p0080', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '蔡邕明堂論云：「更」應作「叟」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-006-93', 'p0080', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」卓怒，罷坐，欲誅植，侍中蔡邕勸之，得免。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-006-94', 'p0080', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '獻帝紀曰：卓旣為太師，復欲稱尚父，以問蔡邕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-006-95', 'p0080', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '謝承後漢書曰：蔡邕在王允坐，聞卓死，有歎惜之音。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-006-96', 'p0080', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '臣松之以為蔡邕雖為卓所親任，情必不黨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-006-97', 'p0080', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '張璠漢紀曰：初，蔡邕以言事見徙，名聞天下，義動志士。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-006-98', 'p0080', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '與楊彪、盧植、蔡邕等典校中書，歷位九卿，遂登台輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-012-99', 'p0080', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '」虎賁士有貌似蔡邕者，融每酒酣，輙引與同坐，曰：「雖無老成人，尚有典刑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-021-100', 'p0080', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '獻帝西遷，粲徙長安，左中郎將蔡邕見而奇之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-021-101', 'p0080', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '陳留路粹、典略曰：粹字文蔚，少學於蔡邕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-021-102', 'p0080', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '漢末又有蔡邕采斯、喜之法，為古今雜形，然精密簡理不如淳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a04-028-103', 'p0080', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '蔡邕有書近萬卷，末年載數車與粲，粲亡後，相國掾魏諷謀反，粲子與焉，旣被誅，邕所與書悉入業。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-011-104', 'p0080', 'jinshu', 'a05-011', '《晉書·卷十一》', '及班固敘漢史，馬遷續述天文，而蔡邕、譙周各有撰錄，司馬彪採之，以繼前志。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-011-105', 'p0080', 'jinshu', 'a05-011', '《晉書·卷十一》', '漢靈帝時，蔡邕於朔方上書，言「宣夜之學，絕無師法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-011-106', 'p0080', 'jinshu', 'a05-011', '《晉書·卷十一》', '蔡邕所謂周髀者，即蓋天之說也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-011-107', 'p0080', 'jinshu', 'a05-011', '《晉書·卷十一》', '又有費直說周易、蔡邕月令章句，所言頗有先後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-011-108', 'p0080', 'jinshu', 'a05-011', '《晉書·卷十一》', '蔡邕月令章句，壽星起軫六度。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-016-109', 'p0080', 'jinshu', 'a05-016', '《晉書·卷十六》', '蔡邕又記建武已後言律呂者，至司馬紹統採而續之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-016-110', 'p0080', 'jinshu', 'a05-016', '《晉書·卷十六》', '至章帝時，其法已絕，蔡邕雖追紀其言，亦曰今無能為者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-017-111', 'p0080', 'jinshu', 'a05-017', '《晉書·卷十七》', '及光和中，乃命劉洪、蔡邕共脩律歷，其後司馬彪因之，以繼班史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-034-112', 'p0080', 'jinshu', 'a05-034', '《晉書-卷三十四・列傳第四》', '祜，蔡邕外孫，景獻皇后同產弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0080-a05-036-full-113', 'p0080', 'jinshu', 'a05-036-full', '《晉書・卷三十六・列傳第六（完整正文）》', '漢末又有蔡邕，采斯喜之法，爲古今雜形，然精密閑理不如淳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a03-070-0', 'p0081', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '又前與白衣禰衡跌蕩於言，跌蕩，無儀檢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a03-080b-1', 'p0081', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '張升　趙壹　劉梁　邊讓　酈炎　侯瑾　高彪　張超　禰衡');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a03-080b-2', 'p0081', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '禰衡字正平，平原般人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a03-080b-3', 'p0081', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '」竊見處士平原禰衡，年二十四，字正平，淑質貞亮，英才卓礫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a03-080b-4', 'p0081', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '操怒，謂融曰：「禰衡豎子，孤殺之猶雀鼠耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a03-080b-5', 'p0081', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '臨發，衆人為之祖道，先供設於城南，乃更相戒曰：「禰衡勃虐無禮，今因其後到，咸當以不起折之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a03-081-6', 'p0081', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '」脩因拜曰：「昔任座面折文侯，解見文苑禰衡傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a04-010-7', 'p0081', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '又平原禰衡傳曰：衡字正平，建安初，自荊州北游許都，恃才傲逸，臧否過差，見不如己者不與語，人皆以是憎之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a04-010-8', 'p0081', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖勑外廄急具精馬三匹，并騎二人，謂融曰：「禰衡豎子，乃敢爾！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a04-012-9', 'p0081', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '此州人說平原禰衡受傳融論，以為父母與人無親，譬若缻器，寄盛其中，又言若遭饑饉，而父不肖，寧贍活餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a04-021-10', 'p0081', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '又與白衣禰衡言論放蕩，衡與融更相贊揚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0081-a04-062-11', 'p0081', 'sanguozhi', 'a04-062', '《三國志·吳書十七》', '綜時侍坐，權問何如，綜對曰：「蕃上書，大語有似東方朔，巧捷詭辯有似禰衡，而才皆不及。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0082-a04-029-0', 'p0082', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '華佗字元化，沛國譙人也，一名旉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0082-a04-029-1', 'p0082', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '」及後愛子倉舒病困，太祖歎曰：「吾悔殺華佗，令此兒彊死也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0082-a04-029-2', 'p0082', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '先持貸我，我差，為卿從華佗更索。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0082-a04-029-3', 'p0082', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '佗別傳曰：人有在青龍中見山陽太守廣陵劉景宗，景宗說中平曰「數見華佗，其治病手脉之候，其驗若神。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0082-a04-029-4', 'p0082', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '評曰：華佗之醫診，杜夔之聲樂，朱建平之相術，周宣之相夢，管輅之術筮，誠皆玄妙之殊巧，非常之絕技矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0083-a04-023-0', 'p0083', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '事見荀粲、傅嘏、王弼、管輅諸傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0083-a04-029-1', 'p0083', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '管輅字公明，平原人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0083-a04-029-2', 'p0083', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '」孔曜言：「平原管輅字公明，年三十六，雅性寬大，與世無忌，可謂士雄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0083-a04-029-3', 'p0083', 'sanguozhi', 'a04-029', '《三國志·魏書二十九》', '評曰：華佗之醫診，杜夔之聲樂，朱建平之相術，周宣之相夢，管輅之術筮，誠皆玄妙之殊巧，非常之絕技矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a04-004-0', 'p0084', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '己未，故漢獻帝夫人節薨，帝臨于華林園，使使持節追謚夫人為獻穆皇后。');
